package net.civeira.phylax.features.oauth.authentication.application.token;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.features.oauth.authentication.domain.exception.OAuthTokenException;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.tokensecurity.application.AccessTokenPolicy;
import net.civeira.phylax.features.oauth.tokensecurity.application.JwtTokenBuilder;
import net.civeira.phylax.features.oauth.tokensecurity.domain.AutorizationToken;
import net.civeira.phylax.features.oauth.tokensecurity.domain.TokenIntrospectionResult;

/**
 * Token exchange for delegation (RFC 8693, task 3.8), the grant that replaces a proprietary
 * {@code delegated} one (task 2.5).
 *
 * <p>
 * Policy:
 * <ul>
 * <li>a confidential client registered for the grant exchanges an access token of this tenant that
 * was issued <em>for it</em> (its id among the audiences): a resource server calling another one on
 * behalf of the user;</li>
 * <li>only access tokens in and out ({@code subject_token_type} and {@code requested_token_type});
 * the actor is always the authenticated client, so an {@code actor_token} is refused, and the new
 * token says so in {@code act} (nested when the subject token was already exchanged);</li>
 * <li>the scope can only narrow the subject token one ({@code invalid_scope}) and the audiences
 * must be registered for the client ({@code invalid_target}); by default the client itself;</li>
 * <li>no refresh nor ID token; the subject keeps its authentication facts.</li>
 * </ul>
 */
@ApplicationScoped
@RequiredArgsConstructor
public class TokenExchangeGrant {

  public static final String GRANT_TYPE = JwtTokenBuilder.TOKEN_EXCHANGE;

  private final AccessTokenPolicy accessTokens;
  private final TokenIssuer issuer;

  public AutorizationToken exchange(TokenGrantRequest request, ClientDetails client) {
    String tenant = request.tenant();
    if (!client.isProtectedWithSecret()) {
      throw OAuthTokenException.unauthorizedClient("Token exchange needs a confidential client");
    }
    String subjectToken = request.param("subject_token");
    if (subjectToken == null
        || !JwtTokenBuilder.ACCESS_TOKEN_TYPE.equals(request.param("subject_token_type"))) {
      throw OAuthTokenException.invalidRequest("An access token subject_token is required");
    }
    String requestedType = request.param("requested_token_type");
    if (requestedType != null && !JwtTokenBuilder.ACCESS_TOKEN_TYPE.equals(requestedType)) {
      throw OAuthTokenException.invalidRequest("Only access tokens can be requested");
    }
    if (request.param("actor_token") != null) {
      throw OAuthTokenException.invalidRequest("The actor is the authenticated client");
    }
    Map<String, Object> subject = accessTokens.validate(tenant, subjectToken, client.getClientId())
        .orElseThrow(() -> OAuthTokenException.invalidGrant("Invalid subject_token"));
    List<String> granted = scopes(subject.get("scope"));
    List<String> requested = TokenParams.scopes(request.param("scope"));
    if (!granted.containsAll(requested)) {
      throw OAuthTokenException.invalidScope("The scope exceeds the subject token");
    }
    Set<String> audiences = new LinkedHashSet<>();
    List<String> body = request.params().get("audience");
    if (body != null) {
      body.stream().filter(a -> a != null && !a.isBlank()).forEach(audiences::add);
    }
    audiences.addAll(TokenParams.resources(request.params()));
    if (audiences.isEmpty()) {
      audiences.add(client.getClientId());
    }
    if (!client.allowsAudiences(List.copyOf(audiences))) {
      throw OAuthTokenException.invalidTarget();
    }
    // The local user comes from the server record: the sub of the token may be pairwise (4.4).
    TokenIntrospectionResult record =
        accessTokens.record(tenant, subject).filter(found -> found.getLocalSubject() != null)
            .orElseThrow(() -> OAuthTokenException.invalidGrant("Invalid subject_token"));
    AuthenticationData data = new AuthenticationData();
    data.setUsername(record.getLocalSubject());
    data.setUid(record.getLocalUid());
    data.setTenant(String.valueOf(subject.get("tid")));
    data.setScopes(new ArrayList<>(requested.isEmpty() ? granted : requested));
    data.setAudiences(new ArrayList<>(audiences));
    if (subject.get("auth_time") instanceof Number time) {
      data.setTime(Instant.ofEpochSecond(time.longValue()));
    }
    if (subject.get("amr") instanceof List<?> amr) {
      data.setAmr(amr.stream().map(String::valueOf).toList());
    }
    Map<String, Object> act = new LinkedHashMap<>();
    act.put("sub", client.getClientId());
    if (subject.get("act") instanceof Map<?, ?> previous) {
      act.put("act", previous);
    }
    return issuer.issueExchanged(tenant, client, data, act);
  }

  private static List<String> scopes(Object scope) {
    if (scope instanceof List<?> list) {
      return list.stream().map(String::valueOf).toList();
    }
    return scope == null ? List.of() : TokenParams.scopes(String.valueOf(scope));
  }
}
